<template><MarketplaceLayout><main class="market-container market-page cart-page"><header class="market-page-heading"><h1>Giỏ hàng</h1><p>Đặt riêng theo từng gian hàng để giữ đúng phí giao nhận và người bán.</p></header><p v-if="loading" role="status">Đang tải giỏ hàng…</p><div v-if="error" role="alert"><p>{{ error }}</p><button class="button button-outline" :disabled="busy" @click="load">Tải lại giỏ hàng</button></div><section v-for="group in groups" :key="group.id" class="cart-store"><h2><RouterLink :to="'/stores/'+group.id">{{ group.name }}</RouterLink></h2><ul><li v-for="line in group.items" :key="line.id"><CatalogImage :src="line.imageUrl" :alt="line.name"/><div><RouterLink :to="'/products/'+line.productId">{{ line.name }}</RouterLink><p>{{ money(line.unitPrice) }} × {{ line.quantity }}</p><p v-if="!line.available || line.stock<line.quantity" role="status">Sản phẩm không còn khả dụng hoặc thiếu tồn kho.</p></div><div class="cart-controls"><label :for="'cart-qty-'+line.id">Số lượng</label><input :id="'cart-qty-'+line.id" :value="line.quantity" type="number" min="1" max="1000000" :disabled="busy" @change="update(line.id,Number($event.target.value))"/><button class="button button-outline" :disabled="busy" @click="update(line.id,0)">Xóa</button></div><strong>{{ money(Number(line.unitPrice)*line.quantity) }}</strong></li></ul><RouterLink :to="'/checkout?store='+group.id" class="button button-primary">Đặt hàng từ {{ group.name }}</RouterLink></section><section v-if="!loading && data && !data.items.length" class="market-empty"><h2>Giỏ hàng đang trống</h2><RouterLink to="/products" class="button button-primary">Khám phá sản phẩm</RouterLink></section></main></MarketplaceLayout></template>
<script setup>
import {computed,onMounted,ref} from 'vue';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import CatalogImage from '../../../components/marketplace/CatalogImage.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {usePage} from '../../../legacy/navigation.js';import {formatPrice} from '../../../utils.js';
const data=ref(null),loading=ref(true),busy=ref(false),error=ref('');const money=v=>formatPrice(v)+' ₫';const groups=computed(()=>{const map=new Map();for(const item of data.value?.items||[]){if(!map.has(item.storeId))map.set(item.storeId,{id:item.storeId,name:item.storeName,items:[]});map.get(item.storeId).items.push(item);}return [...map.values()];});
function apply(result){data.value=result;usePage().props.cartCount=result.quantity;}async function load(){loading.value=true;error.value='';try{apply(await request('/account/cart'));}catch(e){error.value=e.message;}finally{loading.value=false;}}async function update(id,quantity){if(busy.value)return;busy.value=true;error.value='';try{if(!Number.isSafeInteger(quantity)||quantity<0)throw new Error('Số lượng không hợp lệ.');apply(await request('/account/cart/items/'+id,'PUT',{quantity}));}catch(e){error.value=e.message;}finally{busy.value=false;}}onMounted(load);
</script>
<style scoped>.cart-page{padding-bottom:120px;overflow-wrap:anywhere}.cart-store{padding:28px 0;border-top:1px solid var(--bm-border)}.cart-store h2{font-size:var(--bm-type-section)}.cart-store a{color:var(--bm-forest)}.cart-store a.button-primary{color:var(--bm-surface)}.cart-store ul{list-style:none;padding:0}.cart-store li{display:grid;grid-template-columns:80px minmax(0,1fr) auto auto;gap:24px;align-items:center;padding:24px 0;border-top:1px solid var(--bm-border)}.cart-controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.cart-controls input{width:88px;min-height:48px;padding:10px;font:inherit;border:1px solid var(--bm-control-border);border-radius:var(--bm-radius-control)}.cart-store :focus-visible{outline:3px solid var(--bm-forest);outline-offset:3px}@media(max-width:767px){.cart-store li{grid-template-columns:56px minmax(0,1fr);gap:16px}.cart-controls,.cart-store li>strong{grid-column:2}.cart-controls label{width:100%}}</style>
